"""Fixed synthetic document benchmark; generated bytes are never committed."""

import hashlib
import json
import platform
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
from typing import cast

import pymupdf
from pydantic import BaseModel, ConfigDict

from invoiceops.evaluation.supporting_hybrid import (
    ReplayCase,
    SupportingReplayReport,
    _po_candidate,
    _receipt_candidate,
    run_supporting_replay_evaluation,
)
from invoiceops.extraction.errors import DocumentExtractionError, OcrUnavailableError
from invoiceops.extraction.hybrid.schemas import CandidateField, VisionUsage
from invoiceops.extraction.preprocessing import DocumentTextExtractor
from invoiceops.extraction.supporting_hybrid import SupportingResponse
from invoiceops.schemas.cases import DocumentRole

DATASET_ID = "supporting-generated-documents-v1"


@dataclass(frozen=True)
class GeneratedSpec:
    index: int
    role: DocumentRole
    split: str
    source: str
    family: str

    @property
    def case_id(self) -> str:
        return f"{self.role.value.lower()}-{self.index:02d}"


class GeneratedReport(BaseModel):
    model_config = ConfigDict(frozen=True)

    dataset_id: str
    fingerprint: str
    split_counts: dict[str, int]
    holdout_documents: int
    evaluated_documents: int
    schema_validity_on_all_holdout: float
    source_counts: dict[str, int]
    failure_categories: dict[str, int]
    runtime: dict[str, str]
    comparison: SupportingReplayReport | None
    limitations: list[str]


def fixed_specs() -> tuple[GeneratedSpec, ...]:
    roles = (DocumentRole.PURCHASE_ORDER, DocumentRole.GOODS_RECEIPT, DocumentRole.DELIVERY_NOTE)
    return tuple(
        GeneratedSpec(
            index=index,
            role=role,
            split="train" if index < 3 else "development" if index < 5 else "holdout",
            source="image/png" if index % 5 == 0 else "application/pdf",
            family=("standard", "compact", "numbered", "wrapped", "repeated")[index % 5],
        )
        for role in roles
        for index in range(15)
    )


def unseen_specs() -> tuple[GeneratedSpec, ...]:
    """A separate, fixed right-panel layout, never used to choose extraction rules."""
    roles = (DocumentRole.PURCHASE_ORDER, DocumentRole.GOODS_RECEIPT, DocumentRole.DELIVERY_NOTE)
    return tuple(
        GeneratedSpec(
            index=index,
            role=role,
            split="holdout",
            source="image/png" if index % 5 == 0 else "application/pdf",
            family="stacked_panel" if index % 2 else "right_panel",
        )
        for role in roles
        for index in range(10)
    )


def _page_lines(spec: GeneratedSpec) -> list[list[tuple[str, int]]]:
    number = spec.index + 100
    if spec.role == DocumentRole.PURCHASE_ORDER:
        line_header = [
            ("Line", 35),
            ("Item" if spec.family == "compact" else "Description", 100),
            ("Quantity" if spec.family == "compact" else "Qty", 310),
            ("Rate" if spec.family == "compact" else "Price", 420),
            ("Amount", 520),
        ]
        rows = [
            [
                ("1", 35),
                ("12mm bolts" if spec.index % 3 == 0 else "Widgets", 100),
                ("2", 310),
                ("10.00", 420),
                ("20.00", 520),
            ],
            [("2", 35), ("Steel parts", 100), ("3", 310), ("4.00", 420), ("12.00", 520)],
        ]
        if spec.index % 4 == 0:
            rows[1] = rows[1][1:]
        if spec.family == "wrapped":
            rows[0][1] = ("Custom", 100)
            rows.insert(1, [("steel part", 100)])
        return [
            [("Purchase Order No:", 35), (f"PO-{number}", 230)],
            [("Order Date:", 35), ("30/09/2026", 230)],
            [("Vendor:", 35), ("Synthetic Supply Co", 230)],
            [("Currency:", 35), ("INR", 230)],
            line_header,
            *rows,
            [("Subtotal", 35), ("32.00", 520)],
            [("Tax", 35), ("3.20", 520)],
            [("Grand Total", 35), ("35.20", 520)],
        ]
    heading = (
        "Goods Receipt No:" if spec.role == DocumentRole.GOODS_RECEIPT else "Delivery Note No:"
    )
    return [
        [
            (heading, 35),
            (f"{'GR' if spec.role == DocumentRole.GOODS_RECEIPT else 'DN'}-{number}", 230),
        ],
        [("PO No:", 35), (f"PO-{number}", 230)],
        [
            ("Received Date:" if spec.role == DocumentRole.GOODS_RECEIPT else "Delivery Date:", 35),
            ("01/10/2026", 230),
        ],
        [("Supplier:", 35), ("Synthetic Supply Co", 230)],
        [
            ("Item" if spec.family == "compact" else "Description", 35),
            ("Delivered" if spec.family == "compact" else "Received", 310),
            ("Accepted", 420),
            ("Rejected", 520),
        ],
        [("Widgets", 35), ("2", 310), ("2", 420), ("0", 520)],
        [("Steel parts", 35), ("3", 310), ("2", 420), ("1", 520)],
        [("Remarks", 35), ("Synthetic evaluation only", 230)],
    ]


def _truth(spec: GeneratedSpec) -> tuple[dict[str, str], tuple[tuple[str, ...], ...]]:
    number = spec.index + 100
    if spec.role == DocumentRole.PURCHASE_ORDER:
        first_description = (
            "Custom steel part"
            if spec.family == "wrapped"
            else "12mm bolts"
            if spec.index % 3 == 0
            else "Widgets"
        )
        return (
            {"po_number": f"PO-{number}", "issue_date": "2026-09-30", "currency": "INR"},
            (
                (first_description, "2", "10", "20"),
                ("Steel parts", "3", "4", "12"),
            ),
        )
    prefix = "GR" if spec.role == DocumentRole.GOODS_RECEIPT else "DN"
    return (
        {
            "receipt_number": f"{prefix}-{number}",
            "received_date": "2026-10-01",
            "referenced_po_number": f"PO-{number}",
        },
        (("Widgets", "2", "2", "0"), ("Steel parts", "3", "2", "1")),
    )


def generate_bytes(spec: GeneratedSpec) -> bytes:
    pdf = pymupdf.open()  # type: ignore[no-untyped-call]
    rows = _page_lines(spec)
    pages = [rows]
    if spec.family == "repeated":
        pages = [rows[:6], [rows[4], *rows[6:]]]
    for page_rows in pages:
        page = pdf.new_page(width=612, height=792)
        for row_index, row in enumerate(page_rows):
            y = 70 + (29 if spec.family == "compact" else 35) * row_index
            for value, x in row:
                page.insert_text((x, y), value, fontsize=10)
    if spec.source == "image/png":
        # Images are evaluated through the actual OCR path; never borrow PDF tokens.
        body = cast(
            bytes,
            pdf[0]
            .get_pixmap(
                matrix=pymupdf.Matrix(2, 2)  # type: ignore[no-untyped-call]
            )
            .tobytes("png"),
        )
    else:
        body = cast(bytes, pdf.tobytes(garbage=4, deflate=True, no_new_id=True))  # type: ignore[no-untyped-call]
    pdf.close()  # type: ignore[no-untyped-call]
    return body


def _unseen_truth(spec: GeneratedSpec) -> tuple[dict[str, str], tuple[tuple[str, ...], ...]]:
    number = spec.index + 500
    if spec.role == DocumentRole.PURCHASE_ORDER:
        return (
            {"po_number": f"PO-{number}", "issue_date": "2026-09-30", "currency": "INR"},
            (("Synthetic gears", "2", "10", "20"),),
        )
    prefix = "GR" if spec.role == DocumentRole.GOODS_RECEIPT else "DN"
    return (
        {
            "receipt_number": f"{prefix}-{number}",
            "received_date": "2026-10-01",
            "referenced_po_number": f"PO-{number}",
        },
        (("Synthetic gears", "2", "2", "0"),),
    )


def generate_unseen_bytes(spec: GeneratedSpec) -> bytes:
    number = spec.index + 500
    pdf = pymupdf.open()  # type: ignore[no-untyped-call]
    page = pdf.new_page(width=612, height=792)
    if spec.role == DocumentRole.PURCHASE_ORDER:
        headers = [
            ("Purchase Order Number:", f"PO-{number}"),
            ("Order Date:", "30/09/2026"),
            ("Currency:", "INR"),
            ("Vendor:", "Synthetic Supply Co"),
        ]
        table = [("Line", 35), ("Description", 100), ("Qty", 310), ("Price", 420), ("Amount", 520)]
        item = [("1", 35), ("Synthetic gears", 100), ("2", 310), ("10.00", 420), ("20.00", 520)]
    else:
        title = (
            "Goods Receipt Number:"
            if spec.role == DocumentRole.GOODS_RECEIPT
            else "Delivery Note Number:"
        )
        prefix = "GR" if spec.role == DocumentRole.GOODS_RECEIPT else "DN"
        headers = [
            (title, f"{prefix}-{number}"),
            ("Purchase Order Number:", f"PO-{number}"),
            (
                "Received Date:" if spec.role == DocumentRole.GOODS_RECEIPT else "Delivery Date:",
                "01/10/2026",
            ),
            ("Supplier:", "Synthetic Supply Co"),
        ]
        table = [("Description", 35), ("Received", 310), ("Accepted", 420), ("Rejected", 520)]
        item = [("Synthetic gears", 35), ("2", 310), ("2", 420), ("0", 520)]
    y = 65
    for label, value in headers:
        page.insert_text((42, y), label, fontsize=10)
        value_y = y + 18 if spec.family == "stacked_panel" else y
        page.insert_text((350, value_y), value, fontsize=10)
        y += 48
    y += 20
    for text, x in table:
        page.insert_text((x, y), text, fontsize=10)
    y += 35
    for text, x in item:
        page.insert_text((x, y), text, fontsize=10)
    y += 35
    page.insert_text((35, y), "Total", fontsize=10)
    page.insert_text((520, y), "20.00", fontsize=10)
    if spec.source == "image/png":
        body = cast(
            bytes,
            page.get_pixmap(
                matrix=pymupdf.Matrix(2, 2)  # type: ignore[no-untyped-call]
            ).tobytes("png"),
        )
    else:
        body = cast(bytes, pdf.tobytes(no_new_id=True, garbage=4, deflate=True))  # type: ignore[no-untyped-call]
    pdf.close()  # type: ignore[no-untyped-call]
    return body


def _replay(spec: GeneratedSpec) -> SupportingResponse | None:
    # Frozen synthetic replay on a subset; no model invocation or measured tokens.
    if spec.index not in (6, 7):
        return None
    number = spec.index + 100
    if spec.role == DocumentRole.PURCHASE_ORDER:
        candidate = _po_candidate(f"PO-{number}")
    else:
        receipt_candidate = _receipt_candidate(
            f"{'GR' if spec.role == DocumentRole.GOODS_RECEIPT else 'DN'}-{number}"
        )
        receipt_candidate = receipt_candidate.model_copy(
            update={
                "referenced_po_number": CandidateField(
                    raw_value=f"PO-{number}", page=0, evidence_quote=f"PO-{number}", confidence=0.8
                )
            }
        )
        return SupportingResponse(
            candidate=receipt_candidate,
            usage=VisionUsage(input_tokens=100, output_tokens=20),
            latency_ms=10,
        )
    return SupportingResponse(
        candidate=candidate, usage=VisionUsage(input_tokens=100, output_tokens=20), latency_ms=10
    )


def _evaluate_specs(
    specs: tuple[GeneratedSpec, ...],
    *,
    dataset_id: str,
    generate: Callable[[GeneratedSpec], bytes],
    truth_for: Callable[[GeneratedSpec], tuple[dict[str, str], tuple[tuple[str, ...], ...]]],
    replay_for: Callable[[GeneratedSpec], SupportingResponse | None],
) -> GeneratedReport:
    digest = hashlib.sha256()
    examples: list[ReplayCase] = []
    failures: dict[str, int] = {}
    sources: dict[str, int] = {}
    extractor = DocumentTextExtractor()
    for spec in specs:
        body = generate(spec)
        truth, truth_lines = truth_for(spec)
        digest.update(
            json.dumps(
                {
                    "id": spec.case_id,
                    "role": spec.role.value,
                    "split": spec.split,
                    "source": spec.source,
                    "family": spec.family,
                    "truth": truth,
                    "truth_lines": truth_lines,
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode()
        )
        digest.update(hashlib.sha256(body).digest())
        if spec.split != "holdout":
            continue
        sources[spec.source] = sources.get(spec.source, 0) + 1
        try:
            document = extractor.extract(body, spec.source)
        except OcrUnavailableError:
            failures["ocr_unavailable"] = failures.get("ocr_unavailable", 0) + 1
            continue
        except DocumentExtractionError:
            # An unexpected decode failure must be visible in aggregate, without document text.
            failures["document_extraction_failed"] = (
                failures.get("document_extraction_failed", 0) + 1
            )
            continue
        examples.append(
            ReplayCase(spec.case_id, spec.role, document, truth, truth_lines, replay_for(spec))
        )
    comparison = (
        run_supporting_replay_evaluation(tuple(examples), dataset_id=dataset_id)
        if examples
        else None
    )
    holdout_count = sum(spec.split == "holdout" for spec in specs)
    return GeneratedReport(
        dataset_id=dataset_id,
        fingerprint=digest.hexdigest(),
        split_counts={
            name: sum(spec.split == name for spec in specs)
            for name in ("train", "development", "holdout")
        },
        holdout_documents=holdout_count,
        evaluated_documents=len(examples),
        schema_validity_on_all_holdout=len(examples) / holdout_count,
        source_counts=sources,
        failure_categories=failures,
        runtime={
            "python": platform.python_version(),
            "pymupdf": pymupdf.VersionBind,
            "ocr": "available" if "ocr_unavailable" not in failures else "unavailable",
        },
        comparison=comparison,
        limitations=[
            "All documents, truth, and replay are synthetic.",
            "Unprocessed image examples are failures, never surrogate OCR predictions.",
            "Hybrid replay has no live provider; routing is measured, model accuracy is not.",
            "Latency is local and replay provider latency is simulated; no model cost is claimed.",
        ],
    )


def run_generated_holdout() -> GeneratedReport:
    return _evaluate_specs(
        fixed_specs(),
        dataset_id=DATASET_ID,
        generate=generate_bytes,
        truth_for=_truth,
        replay_for=_replay,
    )


def run_unseen_holdout() -> GeneratedReport:
    return _evaluate_specs(
        unseen_specs(),
        dataset_id="supporting-unseen-panel-v1",
        generate=generate_unseen_bytes,
        truth_for=_unseen_truth,
        replay_for=lambda _spec: None,
    )


def write_report(path: Path) -> GeneratedReport:
    report = run_generated_holdout()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(report.model_dump_json(indent=2) + "\n", encoding="utf-8")
    return report


def write_unseen_report(path: Path) -> GeneratedReport:
    report = run_unseen_holdout()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(report.model_dump_json(indent=2) + "\n", encoding="utf-8")
    return report
